#!/usr/bin/env bash
set -euo pipefail
ROOT="TVRemote"
rm -rf "$ROOT"
mkdir -p "$ROOT"
cat > /tmp/tvremote_v3_fixed_payload.b64 <<'PAYLOAD'

PAYLOAD
base64 -d /tmp/tvremote_v3_fixed_payload.b64 > /tmp/tvremote_v3_fixed_payload.zip
python3 - <<'PY'
import zipfile
with zipfile.ZipFile("/tmp/tvremote_v3_fixed_payload.zip") as z:
    z.extractall("TVRemote")
print("TV Remote V3 FIXED project created.")
PY
rm -f /tmp/tvremote_v3_fixed_payload.b64 /tmp/tvremote_v3_fixed_payload.zip
echo "Commit TVRemote, then run Build TV Remote V3 APKs."
